-- Phase 25: the audit trail (SPEC core section 7, "Audit"). One row per audited change, inserted in
-- the same transaction as the change (recordAuditLog in @hamro-pasal/db). The table and its indexes
-- are generated by drizzle-kit; the three triggers at the end are hand-added and make the table
-- APPEND-ONLY for every role: UPDATE, DELETE and TRUNCATE are refused by the database itself.
CREATE TABLE "audit_logs" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"occurred_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
	"actor_user_id" uuid,
	"actor_role" "user_role",
	"system_actor" text,
	"action" text NOT NULL,
	"vendor_id" uuid,
	"entity_type" text NOT NULL,
	"entity_id" uuid NOT NULL,
	"before_state" jsonb,
	"after_state" jsonb NOT NULL,
	"request_id" text,
	"ip_address" "inet",
	"user_agent" text,
	CONSTRAINT "audit_logs_actor_check" CHECK (("audit_logs"."actor_user_id" IS NOT NULL AND "audit_logs"."actor_role" IS NOT NULL AND "audit_logs"."system_actor" IS NULL)
        OR ("audit_logs"."actor_user_id" IS NULL AND "audit_logs"."actor_role" IS NULL AND "audit_logs"."system_actor" IS NOT NULL)),
	CONSTRAINT "audit_logs_system_actor_check" CHECK ("audit_logs"."system_actor" IS NULL OR "audit_logs"."system_actor" ~ '^[A-Z][A-Z0-9_]*$'),
	CONSTRAINT "audit_logs_action_check" CHECK ("audit_logs"."action" ~ '^[A-Z][A-Z0-9_]*$'),
	CONSTRAINT "audit_logs_entity_type_check" CHECK ("audit_logs"."entity_type" ~ '^[a-z][a-z0-9_]*$'),
	CONSTRAINT "audit_logs_before_state_check" CHECK ("audit_logs"."before_state" IS NULL OR jsonb_typeof("audit_logs"."before_state") = 'object'),
	CONSTRAINT "audit_logs_after_state_check" CHECK (jsonb_typeof("audit_logs"."after_state") = 'object')
);
--> statement-breakpoint
ALTER TABLE "audit_logs" ADD CONSTRAINT "audit_logs_actor_user_id_users_id_fk" FOREIGN KEY ("actor_user_id") REFERENCES "public"."users"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "audit_logs" ADD CONSTRAINT "audit_logs_vendor_id_vendors_id_fk" FOREIGN KEY ("vendor_id") REFERENCES "public"."vendors"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "audit_logs_occurred_at_idx" ON "audit_logs" USING btree ("occurred_at","id");--> statement-breakpoint
CREATE INDEX "audit_logs_vendor_idx" ON "audit_logs" USING btree ("vendor_id","occurred_at") WHERE "audit_logs"."vendor_id" IS NOT NULL;--> statement-breakpoint
CREATE INDEX "audit_logs_entity_idx" ON "audit_logs" USING btree ("entity_type","entity_id","occurred_at");--> statement-breakpoint
CREATE INDEX "audit_logs_actor_user_id_idx" ON "audit_logs" USING btree ("actor_user_id") WHERE "audit_logs"."actor_user_id" IS NOT NULL;--> statement-breakpoint

-- Append-only -------------------------------------------------------------------------
-- Hand-added. A wrong entry is corrected by a later entry, never by changing this one.
CREATE FUNCTION reject_audit_log_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'audit_logs is append-only (% rejected)', TG_OP
    USING ERRCODE = 'integrity_constraint_violation';
END;
$$;
--> statement-breakpoint
CREATE TRIGGER audit_logs_append_only BEFORE UPDATE OR DELETE ON audit_logs
  FOR EACH ROW EXECUTE FUNCTION reject_audit_log_mutation();
--> statement-breakpoint
-- Row triggers do not fire for TRUNCATE: it needs its own statement-level trigger.
CREATE TRIGGER audit_logs_no_truncate BEFORE TRUNCATE ON audit_logs
  FOR EACH STATEMENT EXECUTE FUNCTION reject_audit_log_mutation();
